_RT9 = [('יחס שוטף', '={c}2/{c}3', 'num2'), ('הון עצמי מסך הנכסים', '={c}5/{c}4', 'pct1'), ('תשואה על הנכסים (ROA)', '={c}6/{c}4', 'pct1'), ('תשואה על ההון (ROE)', '={c}6/{c}5', 'pct1')]
_HOW9 = ['נכסים שוטפים חלקי התחייבויות שוטפות', 'הון עצמי חלקי סך הנכסים', 'רווח נקי חלקי סך הנכסים', 'רווח נקי חלקי הון עצמי']
_sol, _stp = {}, []
for _i, (_n, _fx, _fm) in enumerate(_RT9):
    _r = 8 + _i; _d[f'A{_r}'] = _n; _d[f'D{_r}'] = _HOW9[_i]
    for _c in 'BC': _sol[f'{_c}{_r}'] = _fx.format(c=_c); _f[f'{_c}{_r}'] = _fm
    _stp.append(dict(cells={f'B{_r}': _fx.format(c='B'), f'C{_r}': _fx.format(c='C')}, note=f'<b>{_n}:</b> {XL(_fx.format(c="B"))}, ובאותה דרך לקפה נועה.', sel=f'B{_r}'))
